-- 016: nurga as it was from Classic to Velious (spawn points, groups and path grids from Quarm).
--
-- The dump has this zone in a later, revamped state. Generated by tools/npc_stats/gen_zone_from_quarm.py
-- (regenerate rather than edit): 92 spawn points, 12 spawn groups, 71 entries from the Quarm database,
-- ids + 1000000. NPCs are ours, matched by name; headings are Quarm's / 1.0198.
-- Level, HP, damage and AC taken from Quarm: a_Sarnak_slave: ours 107139 was level 45, Quarm has 32
-- Level, HP, damage and AC taken from Quarm: a_tortured_slave: ours 107116 was level 45, Quarm has 32
-- Level, HP, damage and AC taken from Quarm: a_fatigued_slave: ours 107118 was level 45, Quarm has 32
--
-- Our rows are kept in spawn2_before_era, spawngroup_before_era, spawnentry_before_era, grid_before_era and
-- grid_entries_before_era. To restore: delete the zone's rows with id >= 1000000 (spawn2, and spawngroup /
-- spawnentry by spawngroupID), delete its grid / grid_entries rows, and insert the *_before_era rows back.
-- Idempotent.

CREATE TABLE IF NOT EXISTS spawn2_before_era LIKE spawn2;
CREATE TABLE IF NOT EXISTS spawngroup_before_era LIKE spawngroup;
CREATE TABLE IF NOT EXISTS spawnentry_before_era LIKE spawnentry;
CREATE TABLE IF NOT EXISTS grid_before_era LIKE grid;
CREATE TABLE IF NOT EXISTS grid_entries_before_era LIKE grid_entries;
CREATE TEMPORARY TABLE era_groups AS SELECT DISTINCT spawngroupID AS id FROM spawn2 WHERE zone = 'nurga' AND id < 1000000
  AND spawngroupID NOT IN (SELECT spawngroupID FROM spawn2 WHERE zone <> 'nurga');
DELETE FROM spawnentry WHERE spawngroupID IN (SELECT id FROM era_groups);
DELETE FROM spawngroup WHERE id IN (SELECT id FROM era_groups);
DELETE FROM spawn2 WHERE zone = 'nurga' AND id < 1000000;
DROP TEMPORARY TABLE era_groups;
DELETE FROM grid_entries WHERE zoneid = 107;
DELETE FROM grid WHERE zoneid = 107;

CREATE TABLE IF NOT EXISTS npc_types_before_era LIKE npc_types;
UPDATE npc_types SET level = 32, hp = 2500, mindmg = 10, maxdmg = 73, AC = 116 WHERE id = 107116;
UPDATE npc_types SET level = 32, hp = 2475, mindmg = 10, maxdmg = 73, AC = 116 WHERE id = 107118;
UPDATE npc_types SET level = 32, hp = 2500, mindmg = 10, maxdmg = 73, AC = 116 WHERE id = 107139;





